entries[421013] = { ["name"] = "Verdammniskultivierung", ["text"] = "Wirken in 6 sek.\nKnorrenwurzel züchtet ' Verdammniswurzeln ' heran. Dadurch wird der Erde Kraft entzogen, die seinen erlittenen Schaden um 99% verringert. Zudem verursacht er alle 5.2 Sek. 43514 Schattenflammenschaden.\n\n' Splitternde Kohle ' fliegt alle 8 Sek. von Knorrenwurzels Körper weg.\n\nDiese Fähigkeit verderbt den Boden unter Knorrenwurzel, erweckt schlafende Kreaturen und erschafft ' Giftlehm '.\n\nDie Zerstörung aller Verdammniswurzeln belegt Knorrenwurzel mit ' Entwurzelte Agonie '." }
entries[421014] = { ["name"] = "Ätzende Explosion", ["text"] = "200 Meter Reichweite\nSofort\nDie Blüte explodiert und entlässt giftige Dämpfe, die 15 Sek. lang allen Spielercharakteren in einem Umkreis von 5 Metern alle 1 Sek. 30 Naturschaden zufügen. Dieser Schaden ist gegen Absorptionsschilde um 200% erhöht." }
entries[421015] = { ["name"] = "Launischer Wutanfall", ["text"] = "100 Meter Reichweite\nSofort\nAurostor beginnt mit einem Wutanfall, zerschmettert den Boden, was Linien aufgeworfener Erde zu seinen Zielen entsendet, die allen getroffenen Spielercharakteren innerhalb von 5 Metern 109176 körperlichen Schaden zufügt." }
entries[421016] = { ["name"] = "Unerbittliches Sperrfeuer", ["text"] = "200 Meter Reichweite\nSofort\nWenn ' Fesselndes Dickicht ' nicht unterbrochen wird, entfesselt Aerwynn 3 Sek. lang ein heftiges Bombardement, das alle 1 Sek. Wurfspeere auf alle Spielercharaktere abfeuert, die Ziele 30 Sek. lang vergiften und ihnen alle 1.5 Sek. 72524 Naturschaden zufügen. Dieser Effekt ist stapelbar." }
