entries[421037] = { ["name"] = "Spitzhacke wuchten", ["text"] = "100 Meter Reichweite\nWirken in 6 sek.\nDer Kerzenkönig bereitet eine übergroße Spitzhacke vor, um sie auf ein Ziel zu wuchten. Die Spitzhacke prallt auf das erste von ihr getroffene Ziel, fügt ihm 29 körperlichen Schaden zu und stößt es zurück. Erwischt sie stattdessen eine Wachsstatue, wird diese dadurch zerschmettert." }
entries[421038] = { ["name"] = "Glutverkohlt", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchattenflammenrückstände verursachen alle 1 Sek. 7252 Schattenflammenschaden. Dieser Effekt ist stapelbar.\n\nDie Berührung von ' Verdammniswurzeln ' unter Einfluss des Effekts entzündet die Wurzel und entfernt eine Anwendung des Effekts." }
