entries[421207] = { ["name"] = "Schlängelnde Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchlangengleiche Flammen umgeben den Spielercharakter, fügen ihm 121987 Feuerschaden zu und strahlen 12 Sek. lang alle 1 Sek. ' Wirbelndes Sengen ' auf Spielercharaktere in der Nähe aus. Die Flammen verdichten sich mit der Zeit, was ihren Effektbereich verkleinert und ihren Schaden erhöht.\nBeim Ablauf wird eine ' Windende Eruption ' ausgelöst." }
