entries[421224] = { ["name"] = "Verwucherte Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nEinige Kräuter, die im Traum wachsen, sind denkende und fühlende Wesen und reagieren panisch auf Versuche, sie zu ernten. Sie entwurzeln sich selbst und fliehen vor etwaigen Möchtegernsammlern. Wer aber entschlossen genug ist, kann vielleicht trotzdem Materialien von diesen Kreaturen sammeln." }
entries[421225] = { ["name"] = "Kurs planen", ["text"] = "Sofort 30 min Abklingzeit\nPlatziert in regelmäßigen Abständen Ringe für Gruppenmitglieder, durch die diese hindurchrasen können.\n\nDie Ringe können nicht zu nahe beieinander platziert werden. Die Abklingzeit ist während des Winterhauchfestes verringert." }
entries[421226] = { ["name"] = "Verwuchertes Steinbrich", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nSteinbrich ist ein widerstandsfähiges Kraut, das an zahlreichen Orten gedeihen kann. Obwohl es allgemein an felsigen Standorten wie Gebirgen oder Klippen auffindbar ist, wächst es auch auf weiten Ebenen oder vereinzelt in vulkanischen Gebieten.\n\nEinige Kräuter, die im Traum wachsen, sind denkende und fühlende Wesen und reagieren panisch auf Versuche, sie zu ernten. Sie entwurzeln sich selbst und fliehen vor etwaigen Möchtegernsammlern. Wer aber entschlossen genug ist, kann vielleicht trotzdem Materialien von diesen Kreaturen sammeln." }
entries[421227] = { ["name"] = "Verwucherte Krümmrinde", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKrümmrinde ist ein grünliches Kraut, das auf den Dracheninseln gefunden werden kann. Es wächst dort, wo es reichlich Bäume oder Grünpflanzen gibt.\n\nEinige Kräuter, die im Traum wachsen, sind denkende und fühlende Wesen und reagieren panisch auf Versuche, sie zu ernten. Sie entwurzeln sich selbst und fliehen vor etwaigen Möchtegernsammlern. Wer aber entschlossen genug ist, kann vielleicht trotzdem Materialien von diesen Kreaturen sammeln." }
entries[421228] = { ["name"] = "Schlängelnde Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchlangengleiche Flammen umgeben den Spielercharakter, fügen ihm 4 Feuerschaden zu und strahlen 12 Sek. lang alle 1 Sek. ' Wirbelndes Sengen ' auf Spielercharaktere in der Nähe aus. Die Flammen verdichten sich mit der Zeit, was ihren Effektbereich verkleinert und ihren Schaden erhöht." }
entries[421230] = { ["name"] = "Rennring", ["text"] = "Sofort\nErstellt einen Rennring." }
entries[421234] = { ["name"] = "Hilfspaket platzieren" }
entries[421235] = { ["name"] = "Streckenreiter", ["text"] = "Sofort\nRast durch die Strecken anderer Spielercharaktere!" }
entries[421236] = { ["name"] = "Lied des Drachen", ["text"] = "200 Meter Reichweite\nSofort\nBei 100 Energie singt Pip ein fesselndes Lied und lässt alle Spielercharaktere 196278 Schaden durch ' Ätzende Pollen ' absorbieren." }
entries[421240] = { ["name"] = "Streckensignalgeber", ["text"] = "Unbegrenzte Reichweite\nSofort\nPlatziert glitzernde Ringe für andere Spielercharaktere, durch die diese hindurchrasen können!" }
