entries[421244] = { ["name"] = "Lebendes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nErzvorkommen, die von den mächtigen Naturkräften des Traums beeinflusst wurden, erwachen zum Leben und fliehen vor etwaigen Möchtegernausbeutern, die sie abbauen könnten." }
entries[421245] = { ["name"] = "Einschläferndes Brüllen", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 3.5 sek.)\nAurostor brüllt und fügt allen Gegnern 69475 Naturschaden zu. Zusätzlich erhalten Spielercharaktere 3 Stapel von ' Einschläferndes Brüllen ' und werden 14 Sek. lang um 25% pro Stapel verlangsamt.\n\nSpringen entfernt einen Stapel von ' Einschläferndes Brüllen '." }
entries[421247] = { ["name"] = "Lebendes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nErzvorkommen, die von den mächtigen Naturkräften des Traums beeinflusst wurden, erwachen zum Leben und fliehen vor etwaigen Möchtegernausbeutern, die sie abbauen könnten." }
