entries[421256] = { ["name"] = "Ultimative Bußfertigkeit", ["text"] = "Jedes Mal, wenn 'Sühne' Schaden verursacht oder Heilung hervorruft, sammelt sich ein Teil dieser Kraft in Euch an. Nach dem Stapeln von 30 Blitzen kann der Effekt aktiviert werden, sodass Ihr in die Luft aufsteigt und auf Gegner und Verbündete in der Nähe ein Sperrfeuer von durch 'Sühne' erzeugten Blitzen abfeuert.\n\nIn der Luft haben zudem Rückstöße oder Kontrollverlusteffekte keinen Einfluss auf Euch." }
entries[421260] = { ["name"] = "Einschläferndes Brüllen", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nAurostor brüllt und fügt allen Gegnern 69475 Naturschaden zu. Zusätzlich erhalten Spielercharaktere 3 Stapel von ' Einschläferndes Brüllen ' und werden 14 Sek. lang um 25% pro Stapel verlangsamt.\n\nSpringen entfernt einen Stapel von ' Einschläferndes Brüllen '." }
