entries[421274] = { ["name"] = "Dunkelflammenspitzhacke", ["text"] = "100 Meter Reichweite\nSofort 5 sek. Abklingzeit\nDer Kerzenkönig bereitet eine übergroße Spitzhacke vor, um sie auf ein Ziel zu wuchten. Die Spitzhacke prallt auf das erste von ihr getroffene Ziel, fügt ihm 29 körperlichen Schaden zu und stößt es zurück. Erwischt sie stattdessen eine Wachsstatue, wird diese dadurch zerschmettert." }
entries[421277] = { ["name"] = "Dunkelflammenspitzhacke", ["text"] = "100 Meter Reichweite\nWirken in 6 sek.\nDer Kerzenkönig bereitet eine Spitzhacke vor, um sie auf ein Ziel zu werfen. Die Spitzhacke prallt auf das erste von ihr getroffene Ziel, fügt ihm 6976571 Schattenschaden zu und stößt es zurück. Erwischt sie stattdessen eine Wachsstatue, wird diese dadurch zerschmettert." }
entries[421278] = { ["name"] = "Suche nach brennendem Boden einstellen", ["text"] = "Sofort\nDer Treant hört auf, nach brennendem Boden zu suchen." }
entries[421279] = { ["name"] = "Verletzlicher Schlummer", ["text"] = "100 Meter Reichweite\nSofort\nDas Ziel wird in den Schlaf versetzt. Der erlittene Schaden wird um 100% erhöht.\n\nDas Erleiden von Schaden entfernt diesen Effekt." }
