entries[421292] = { ["name"] = "Fesselndes Dickicht", ["text"] = "Wirken in 4 sek.\nBei 100 Energie beschwört Aerwynn für 18 Sek. Ranken, die auf alle Spielercharaktere eindreschen, ihnen alle 1 Sek. 29009 Naturschaden zufügen und ihre Bewegungsgeschwindigkeit um 7% verringern. Dieser Effekt ist stapelbar und die Stapel erhöhen sich alle 3 Sek.\n\nDiese Kanalisierung macht Aerwynn anfällig für ' Unkontrollierter Ansturm '." }
entries[421298] = { ["name"] = "Fesselndes Dickicht", ["text"] = "200 Meter Reichweite\nSofort\nBei 100 Energie beschwört Aerwynn für 18 Sek. Ranken, die auf alle Spielercharaktere eindreschen, ihnen alle 1 Sek. 29009 Naturschaden zufügen und ihre Bewegungsgeschwindigkeit um 7% verringern. Dieser Effekt ist stapelbar und die Stapel erhöhen sich alle 3 Sek.\n\nDiese Kanalisierung macht Aerwynn anfällig für ' Unkontrollierter Ansturm '." }
