entries[421315] = { ["name"] = "Verzehrende Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nNach 3 Einsätzen von 'Flammendes Inferno' schöpft Larodar 16 Sek. lang aus den Flammen in der Umgebung, fügt dabei allen Spielercharakteren alle 0.5 Sek. 116038 Feuerschaden zu und zieht diese zu sich. Zusätzlich fügt der Hüter Spielercharakteren innerhalb von 3 Metern 108785 Feuerschaden zu.\n\nLarodar geht dadurch in Flammen auf, wodurch er in den Avatar der Asche verwandelt wird." }
entries[421316] = { ["name"] = "Verzehrende Flamme", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nNach 3 Einsätzen von 'Flammendes Inferno' schöpft Larodar 16 Sek. lang aus den Flammen in der Umgebung, fügt dabei allen Spielercharakteren alle 0.5 Sek. 116038 Feuerschaden zu und zieht diese zu sich. Zusätzlich fügt der Hüter Spielercharakteren innerhalb von 3 Metern 108785 Feuerschaden zu.\n\nLarodar geht dadurch in Flammen auf, wodurch er in den Avatar der Asche verwandelt wird." }
