entries[421318] = { ["name"] = "Qualmende Pyrolyse", ["text"] = "100 Meter Reichweite\nSofort\nLarodars aschene Hülle entfesselt eine brutale Rauchgasexplosion, die in einem frontalen kegelförmigen Bereich 1305426 Feuerschaden verursacht und ' Qualmendes Ersticken ' hervorruft." }
entries[421319] = { ["name"] = "Aschene Erde", ["text"] = "300 Meter Reichweite\nSofort\nDurch Larodars Transformation wird sämtlicher 'Brennender Boden' zu 'Aschene Erde'.\n\nErleidet ein Ziel im Bereich von 'Aschene Erde' Feuerschaden, brechen alle Bereiche von 'Aschene Erde' aus und fügen allen Spielercharakteren im Wirkungsbereich 0 Feuerschaden zu." }
