entries[421326] = { ["name"] = "Entfachung", ["text"] = "Unbegrenzte Reichweite\nSofort\nLarodar versucht, mehrere Spielercharaktere mit einem Feuerblitz zu treffen und lässt sie 8 Sek. lang 654259 Heilung absorbieren. Nach 8 Sek. bricht jeder Spielercharakter aus und fügt Spielercharakteren in einem Umkreis von 8 Metern 290095 Feuerschaden zu.\n\nWenn die Absorption nicht vor Ablauf geheilt wird, belegt ' Entfachung ' getroffene Spielercharaktere zusätzlich mit ' In Asche eingeschlossen '." }
entries[421328] = { ["name"] = "Fallende Glut", ["text"] = "Unbegrenzte Reichweite\nSofort\nLarodar gibt eine Handvoll Glut frei, die vom Himmel regnet und Spielercharakteren innerhalb von 3 Metern um die Einschlagsbereiche 290095 Feuerschaden zufügt.\n\nGlut, die keine Spielercharaktere trifft, fügt allen Spielercharakteren 580189 Feuerschaden zu und belegt diese mit einem Stapel von ' Sengende Asche '." }
