entries[421350] = { ["name"] = "Splitternde Kohle", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrennende Kohlestückchen werden von Knorrenwurzel weggeschleudert, fügen Spielercharakteren im Umkreis von 5 Metern um die Einschlagsorte 36262 Schattenflammenschaden zu und belegen sie mit ' Glutverkohlt '.\n\nJedes Kohlestückchen, das keinen Spielercharakter trifft, explodiert bei Kontakt mit dem Boden und fügt allen Spielercharakteren 108785 Schattenflammenschaden zu." }
