entries[421355] = { ["name"] = "Waffen augmentieren", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 22 sek. Abklingzeit\nErhöht den Schaden der automatischen Angriffe aller Verbündeten um 40% und verringert den erlittenen Schaden um 20%. Hält 16 Sek. lang an." }
entries[421356] = { ["name"] = "Sengschweifsturz", ["text"] = "Unbegrenzte Reichweite\nSofort\nVolcoross' feuriger Schweif taucht aus der Lava auf, schlägt auf den ihn umgebenden Ring ein, fügt getroffenen Spielercharakteren 3626183 körperlichen Schaden zu und stößt sie zurück. Eine geschmolzene Schockwelle fügt allen Spielercharakteren 72524 Feuerschaden zu." }
