entries[421368] = { ["name"] = "Zunichte machen", ["text"] = "Unbegrenzte Reichweite\nSofort\nNymue kanalisiert ihre gewaltige Macht, um alle Spielercharaktere zu beseitigen. Verursacht alle 3 Sek. 108785 Naturschaden und erhöht den durch ' Zunichte machen ' erlittenen Schaden um 10%. Dieser Effekt ist stapelbar." }
entries[421373] = { ["name"] = "Zwergenmedizin", ["text"] = "Brann wirft Heiltränke in die Nähe verletzter Spielercharaktere, die beim Hindurchlaufen eine moderate Menge Gesundheit wiederherstellen." }
entries[421376] = { ["name"] = "Relikt von Uldum", ["text"] = "Brann schwingt ein mächtiges uraltes Relikt, das heilige Energie ausstrahlt und Verbündete 20 Sek. lang alle 1 Sek. um eine erhebliche Menge Gesundheit heilt." }
entries[421378] = { ["name"] = "Dreißig Meter Seil", ["text"] = "Brann wirft Spielercharakteren sein Seil zu, um sie von Betäubungs-, Bewegungsunfähigkeits- und Verlangsamungseffekten zu befreien. Diese werden dadurch 4 Sek. lang immun gegenüber allen derartigen Effekten." }
