entries[421380] = { ["name"] = "Läuternde Salbe", ["text"] = "Brann verschießt Beruhigungspfeile auf ermächtigte Gegner, die 1 Wut-- und 1 Magieeffekte aufheben." }
entries[421382] = { ["name"] = "Branns episches Ei", ["text"] = "Brann beschwört ein Teufelssaurierei. Hoffentlich schlüpft es." }
entries[421383] = { ["name"] = "Wasserstoß" }
entries[421387] = { ["name"] = "Affenleine", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Branns Affenbegleiter Glibb für 15 Sek. an Eure Seite zu rufen, mitsamt Bananen in der Hand.\n\nAspekt des Affen\nGlibbs Anwesenheit verleiht Euch Macht und erhöht Geschwindigkeit, Vermeidung und Lebensraub um 845 .\n\nBöser Affe\nGlibb macht einen Aufstand, fügt Gegnern in der Nähe gewaltigen körperlichen Schaden zu und hat eine Chance, sie für 3 Sek. zu betäuben." }
entries[421389] = { ["name"] = "Frostfalle", ["text"] = "Wenn 3 oder mehr Gegner einen Verbündeten angreifen, schleudert Brann eine Frostfalle auf sie, die ihre Bewegungsgeschwindigkeit um 50% verringert und sie gelegentlich 3 Sek. lang festhält. Die Falle bleibt 15 Sek. lang bestehen." }
entries[421395] = { ["name"] = "Notvorräte", ["text"] = "Wenn die Gesundheit eines Spielercharakters unter 30% fällt, heilt Brann ihn sofort um 25% seiner maximalen Gesundheit. Kann nur alle 3 Min. auftreten." }
entries[421397] = { ["name"] = "Gryphadins Kampfharnisch", ["text"] = "Brann ruft seinen treuen Greifengefährten herbei. Dieser bombardiert Gegner in der Nähe und fügt ihnen dabei 10 Sek. lang alle 1 Sek. erheblichen Schaden zu." }
entries[421398] = { ["name"] = "Feuerstrahl", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nTindral beschießt die Plattform mit Feuerstrahlen, die Spielercharakteren im Umkreis von 15 Metern um den Einschlagsbereich 2538328 Feuerschaden zufügen. Dieser Einschlag erzeugt mehrere sich bewegende Strahlen, die Spielercharakteren in ihnen alle 1 Sek. 1450473 Feuerschaden zufügen." }
entries[421399] = { ["name"] = "Sonnenstrahl" }
entries[421400] = { ["name"] = "Durchbohrender Ansturm", ["text"] = "20 Meter Reichweite\nWirken in 1 sek. 11 sek. Abklingzeit\nDer Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, 11 körperlichen Schaden zu." }
