entries[421419] = { ["name"] = "In voller Blüte", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Nymue 100% Energie erreicht, lässt sie eine überwältigende Woge der Lebensenergie frei, die Spielercharakteren innerhalb von 16 Metern 797760 Naturschaden zufügt und ihnen ' Infloreszenz ' gewährt.\n\nDie Woge fließt dann nach außen, wo sie zu 2 mächtigen Kreiswächtern verschmilzt." }
entries[421421] = { ["name"] = "Verdammniskultivierung", ["text"] = "500 Meter Reichweite\nSofort\nKnorrenwurzel züchtet ' Verdammniswurzeln ' heran. Dadurch wird der Erde Kraft entzogen, die seinen erlittenen Schaden um 99% verringert. Zudem verursacht er alle 5.2 Sek. 43514 Schattenflammenschaden.\n\n' Splitternde Kohle ' fliegt alle 8 Sek. von Knorrenwurzels Körper weg.\n\nDiese Fähigkeit verderbt den Boden unter Knorrenwurzel, erweckt schlafende Kreaturen und erschafft ' Giftlehm '.\n\nDie Zerstörung aller Verdammniswurzeln belegt Knorrenwurzel mit ' Entwurzelte Agonie '." }
entries[421422] = { ["name"] = "Konstruktionsfenster: Eadweards Notizen, Fortsetzung" }
entries[421427] = { ["name"] = "Splitternde Kohle", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrennende Kohlestückchen werden von Knorrenwurzel weggeschleudert, fügen Spielercharakteren im Umkreis von 5 Metern um die Einschlagsorte 36262 Schattenflammenschaden zu und belegen sie mit ' Glutverkohlt '.\n\nJedes Kohlestückchen, das keinen Spielercharakter trifft, explodiert bei Kontakt mit dem Boden und fügt allen Spielercharakteren 108785 Schattenflammenschaden zu." }
