entries[421455] = { ["name"] = "Überhitzt", ["text"] = "300 Meter Reichweite\nSofort\nGlimmeron entzündet mehrere Spielercharaktere und lässt sie 10 Sek. lang alle 2 Sek. Spielercharakteren innerhalb von 5 Metern 97907 Feuerschaden zufügen.\n\nNach Ablauf explodieren die Spielercharaktere und fügen Spielercharakteren innerhalb von 5 Metern 217571 Feuerschaden zu und stoßen ' Flammenwellen ' aus." }
entries[421456] = { ["name"] = "Entfachung", ["text"] = "Unbegrenzte Reichweite\nSofort\nLarodar versucht, mehrere Spielercharaktere mit einem Feuerblitz zu treffen und lässt sie 8 Sek. lang 654259 Heilung absorbieren. Nach 8 Sek. bricht jeder Spielercharakter aus und fügt Spielercharakteren in einem Umkreis von 8 Metern 290095 Feuerschaden zu.\n\nWenn die Absorption nicht vor Ablauf geheilt wird, belegt ' Entfachung ' getroffene Spielercharaktere zusätzlich mit ' In Asche eingeschlossen '." }
