entries[421594] = { ["name"] = "Qualmendes Ersticken", ["text"] = "Unbegrenzte Reichweite\nSofort\nErstickt einen Spielercharakter, wodurch dieser 18 Sek. lang 100% weniger Heilung erhält und alle 1 Sek. 145047 Feuerschaden erleidet.\n\nDieser Effekt entzieht zusätzlich Verbündeten innerhalb von 6 Metern alle 1 Sek. 58011 Gesundheit." }
