entries[422052] = { ["name"] = "Unkontrollierter Ansturm", ["text"] = "200 Meter Reichweite\nSofort\nUrctos konzentriert sich 5 Sek. lang auf das aktuelle Ziel, greift dann an und fügt allen Spielercharakteren in seiner Bahn 145047 körperlichen Schaden zu. Überrannte Ziele werden geschwächt, was den durch ' Unkontrollierter Ansturm ' erlittenen Schaden 30 Sek. lang um 500% erhöht.\n\nWenn er sein Ziel erreicht, entfesselt Urctos ' Donnernder Einschlag '." }
