entries[422276] = { ["name"] = "Brennende Wurzeln", ["text"] = "Wirken in 2 sek.\n'Brennende Wurzeln' brechen aus Tindral hervor, verursachen alle 1 Sek. 8 Feuerschaden, machen Spielercharaktere im Umkreis von 5 Metern um den Einschlag bewegungsunfähig und fügen ihnen 60 Feuerschaden zu.\n\nJede Wurzel, die keinen Spielercharakter trifft, löst ' Flammender Baum ' aus." }
