entries[422303] = { ["name"] = "Klinge versenken", ["text"] = "6 Meter Reichweite\nSofort 1.5 min Abklingzeit\nStößt eine verdrehte Klinge in Euer Ziel und verursacht 1448 körperlichen Schaden. Nach 3 Sek. strömt Schattenflamme aus der Klinge und sie kehrt zu Euch zurück, wobei sie 3548 Schattenflammenschaden verursacht, der zwischen dem Ziel und allen Gegnern in ihrer Bahn aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5." }
