entries[422306] = { ["name"] = "Traumeinstimmung", ["text"] = "Wirken in 8 sek.\nDas Überladen eines verwucherten Krauts vertieft kurzzeitig Eure Verbindung mit dem Traum und stimmt Euch auf Eure Umgebung und das Kraut selbst ein.\n\nNach dem erfolgreichen Abschluss einer kurzen Meditation wird Euch das verwucherte Kraut zahlreiche Ressourcen schenken." }
