entries[422324] = { ["name"] = "Flammender Baum", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin ' Flammender Baum ' sprießt nach 10 Sek. aus einer ' Saat der Flamme ' und fügt Spielercharakteren alle 2 Sek. 507666 Feuerschaden zu." }
