entries[422326] = { ["name"] = "Erdens Führung", ["text"] = "25 Meter ReichweiteWirken in 10 sek. 30 min Abklingzeit\nTeile Erdens Notizen mit einem verbündeten Lederverarbeiter und bringe ihm vorübergehend bei, wie man Erdens Traumlaubgriff herstellt. Der Lederverarbeiter muss sich in der gleichen Gruppe befinden." }
entries[422327] = { ["name"] = "Lydiaras Führung", ["text"] = "25 Meter ReichweiteWirken in 10 sek. 30 min Abklingzeit\nTeilt Lydiaras Notizen mit einem wohlgesinnten Inschriftenkundigen, um ihm vorübergehend beizubringen, wie Lydiaras Bindungsrune hergestellt werden kann. Der Inschriftenkundige muss sich in der gleichen Gruppe befinden." }
entries[422328] = { ["name"] = "Shalasars Führung", ["text"] = "25 Meter ReichweiteWirken in 10 sek. 30 min Abklingzeit\nTeile Shalasars Notizen mit einem verbündeten Verzauberer und bringe ihm vorübergehend bei, wie man Shalasars weises Pergament herstellt. Der Verzauberer muss sich in der gleichen Gruppe befinden." }
entries[422329] = { ["name"] = "Auren des Meisterkunsthandwerkers beseitigen" }
entries[422330] = { ["name"] = "Erdens Leuchtsporengriff", ["text"] = "Wirken in 15 sek.\nReagenzien:\nZaralekleuchtsporen (400), Obsidiankobrahaut (3), Traumlaubgriffprototyp , Träumende Essenz (5), Morastschlickbalg (50)\nErdens provisorisches Rezept für den symbiotischen Leuchtsporengriff. In seinen Notizen werden einige Reagenzien aufgeführt, die zur Erhaltung der symbiotischen Eigenschaften des Griffs nötig sind.\nErdens Traumlaubgriff\nWird beim Aufheben gebunden\n\"Ein Griffprototyp, den Erden aus ledrigem Traumlaub hergestellt hat.\"" }
entries[422331] = { ["name"] = "Entzündender Funke", ["text"] = "Unbegrenzte Reichweite\nSofort\nFunken des brennenden Baumes bedecken das Schlachtfeld und erhöhen den erlittenen Feuerschaden von Spielercharakteren um 5%." }
