entries[422333] = { ["name"] = "Saat der Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\n'Saat der Flamme' heftet sich an den Spielercharakter und verursacht alle 1 Sek. 7 Feuerschaden.\n\nDie Saat bricht nach 6 Sek. aus, fügt Spielercharakteren im Umkreis von 10 Metern 30 Feuerschaden zu und ein wütender Treant erhebt sich von der Position des Spielercharakters." }
