entries[422337] = { ["name"] = "Lydiaras Bindungsrune", ["text"] = "Wirken in 15 sek.\nReagenzien:\nSchattenflammenessenz (10), Bindungsrunenprototyp , Kosmische Tinte (250), Runenverzierte Krümmrinde (50)\nNotizen, in denen die Reagenzien aufgelistet werden, die zur Herstellung von Lydiaras Bindungsrune benötigt werden.\nLydiaras Bindungsrune\nWird beim Aufheben gebunden\n\"In Zusammenarbeit mit Lydiara Flüsterfeder gefertigt.\"" }
entries[422338] = { ["name"] = "Shalasars weises Pergament", ["text"] = "Wirken in 15 sek.\nReagenzien:\nErwecktes Feuer (150), Erweckte Erde (100), Erweckte Ordnung (50), Resonierender Kristall (200), Ordungspergamentprototyp\nShalasars Notizen, in denen er detailliert beschreibt, wie man den Prototyp eines weisen Pergaments herstellt.\nShalasars weises Pergament\nWird beim Aufheben gebunden\n\"In Zusammenarbeit mit Shalasar Glimmerstaub gefertigt.\"" }
