entries[422369] = { ["name"] = "Dornenschmettern", ["text"] = "10 Meter Reichweite\nSofort 1 sek. Abklingzeit\nDornenbedeckte Fäuste schmettern auf den Boden und fügen allen Gegnern vor Euch 12 körperlichen Schaden sowie anderen Gegnern in der Nähe zusätzlichen Schaden zu." }
