entries[422373] = { ["name"] = "Giftlehm", ["text"] = "500 Meter Reichweite\nSofort\nGiftige Erde fügt Spielercharakteren innerhalb von 6 Metern um Knorrenwurzel herum alle 1 Sek. 870284 Schattenflammenschaden zu und verringert deren Bewegungsgeschwindigkeit um 80%. Dieser Schwächungseffekt verringert auch die Stärke erzwungener Bewegungseffekte." }
