entries[422377] = { ["name"] = "Mal von Vyranoth", ["text"] = "Sofort\nEin von Vyranoth verliehenes Mal, dass Euch als ihren Auserwählten kennzeichnet. Die Primalisten in der Sengenden Schlucht werden es erkennen." }
entries[422378] = { ["name"] = "Tollkühner Ansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer alte Wachsbart befiehlt Docht, auf den am weitesten entfernten Spielercharakter zuzustürmen. Dieser Angriff stößt alles in seinem Weg zurück, fügt allen Spielercharakteren 6061123 körperlichen Schaden zu und löst am Ende des Ansturms einen ' Einsturz ' aus.\n\nTödlich für Schuftknechte und Schuftmägde." }
