entries[422381] = { ["name"] = "Wilde Synthese", ["text"] = "Pflege\n'Nachwachsen' verringert die Zauberzeit Eures nächsten Einsatzes von 'Pflege' um 33% und bewirkt, dass die Fähigkeit einen zusätzlichen Bonus von 33% durch ' Meisterschaft: Harmonie ' erhält. Bis zu 3-mal stapelbar.\n\nHainwächter\nTreants von 'Hainwächter' wirken 'Wildwuchs', wenn sie beschworen werden.\n(100ms Abklingzeit)" }
entries[422382] = { ["name"] = "Wildwuchs", ["text"] = "40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nHeilt bis zu 5 verletzte Verbündete innerhalb von 40 Metern um das Ziel im Verlauf von 7 Sek. um (34.272% der Zaubermacht) Gesundheit. Die Heilung ist anfangs größer und nimmt im Laufe der Zeit ab." }
