entries[422389] = { ["name"] = "Aschewurzeln", ["text"] = "300 Meter Reichweite\nSofort\nLarodar lässt die Asche seiner gefallenen Wurzeln auferstehen, die sich dann auf Spielercharaktere fixieren und Spuren von ' Aschene Erde ' hinterlassen." }
